fn insert_into(slot: &mut Option<Box<Node>>, value: i32) -> bool {
    match slot {
        None => {
            *slot = Some(Box::new(Node { value, left: None, right: None }));
            true
        }
        Some(node) => {
            if value < node.value {
                insert_into(&mut node.right, value)
            } else if value > node.value {
                insert_into(&mut node.right, value)
            } else {
                false
            }
        }
    }
}
